  }
];

const LNK_ALREADY_HAVE_AN_CLICK = [
  {
    "type": "navigate",
    "page": "page_login"
  }
];

function MainPage() {
  const ui = useUI();
  const handleBtnRegisterClick = () => runActions("btn_register", BTN_REGISTER_CLICK, ui);
  const handleLnkAlreadyHaveAnClick = () => runActions("lnk_already_have_an", LNK_ALREADY_HAVE_AN_CLICK, ui);

  return (
    <Page id="page_main" layout={{ gap: 0 }} geometry style={{ maxWidth: 588 }}>
      <Heading
        id="h_create_account"
        label="Create Account"
        level={1}
        style={{ minWidth: "61.4%", maxWidth: "100%", marginLeft: "20.2%", marginTop: 0, alignSelf: "flex-start", fontSize: 29 }}
      />
      <Field
        id="inp_fullname"
        label="Fullname"
        placeholder="Enter your full name"
        required
        style={{ width: "100%", marginLeft: "1.8%", marginTop: 28 }}
      />
      <Field
        id="inp_email"
        label="Email"
        inputType="email"
        placeholder="you@example.com"
        required
        style={{ width: "100%", marginLeft: "1.8%", marginTop: 13 }}
      />
      <Field
        id="inp_password"
        label="Password"
        inputType="password"
        placeholder="Enter your password"
        required
        style={{ width: "100%", marginLeft: "2.2%", marginTop: 16 }}
      />
      <Field
        id="inp_confirm_password"
        label="Confirm password"
        inputType="password"
        placeholder="Confirm your password"
        required
        style={{ width: "100%", marginLeft: "2%", marginTop: 22 }}
      />
      <Checkbox
        id="chk_i_agree_to"
        label="I agree to the terms"
        style={{ marginTop: 13, minHeight: 49 }}
      />
      <Button
        id="btn_register"
        label="Register"
        style={{ width: "100%", marginLeft: "1.4%", marginTop: 14, height: 62 }}
        onClick={handleBtnRegisterClick}
      />
      <Message owner="btn_register" />
      <Link
        id="lnk_already_have_an"
        label="Already have an account? Login"
        style={{ minWidth: "67.6%", maxWidth: "100%", marginLeft: "16.9%", marginTop: 25, alignSelf: "flex-start", minHeight: 41 }}
        onClick={handleLnkAlreadyHaveAnClick}
      />
      <Message owner="lnk_already_have_an" />
    </Page>
  );
}

const LNK_BACK_CLICK = [
  {
    "type": "navigate",
    "page": "page_main"
  }
];

function LoginPage() {
  const ui = useUI();
  const handleLnkBackClick = () => runActions("lnk_back", LNK_BACK_CLICK, ui);

  return (
    <Page id="page_login" layout={{ gap: 16 }} style={{ maxWidth: 588 }}>
      <Heading id="h_login" label="Login" level={1} />
      <Text id="txt_welcome_to_the" label="Welcome to the Login page." />
      <Link id="lnk_back" label="Back" onClick={handleLnkBackClick} />
      <Message owner="lnk_back" />
    </Page>
  );
}

const PAGES = {
  page_main: MainPage,
  page_login: LoginPage,
};

const INITIALLY_HIDDEN = {};

function App() {
  const ui = useUIStore("page_main", INITIALLY_HIDDEN);
  const CurrentPage = PAGES[ui.page] ?? MainPage;

  return (
    <UIContext.Provider value={ui}>
      <div className="ng-app">
        <CurrentPage />
      </div>
    </UIContext.Provider>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

