const LNK_BACK_CLICK = [
  {
    "type": "navigate",
    "page": "page_main"
  }
];

function LoginPage() {
  const ui = useUI();
  const handleLnkBackClick = () => runActions("lnk_back", LNK_BACK_CLICK, ui);

  return (
    <Page id="page_login" layout={{ gap: 16 }} style={{ maxWidth: 588 }}>
      <Heading id="h_login" label="Login" level={1} />
      <Text id="txt_welcome_to_the" label="Welcome to the Login page." />
      <Link id="lnk_back" label="Back" onClick={handleLnkBackClick} />
      <Message owner="lnk_back" />
    </Page>
  );
}

const PAGES = {
  page_main: MainPage,
  page_login: LoginPage,
};

const INITIALLY_HIDDEN = {};

function App() {
  const ui = useUIStore("page_main", INITIALLY_HIDDEN);
  const CurrentPage = PAGES[ui.page] ?? MainPage;

  return (
    <UIContext.Provider value={ui}>
      <div className="ng-app">
        <CurrentPage />
      </div>
    </UIContext.Provider>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);
